import{_ as o,C as t,o as i,c as s,E as a,a2 as c}from"./chunks/framework.BdWD-ld-.js";const v=JSON.parse('{"title":"Deployment, Channel, Action: What Each Approval Actually Decides","description":"","frontmatter":{"title":"Deployment, Channel, Action: What Each Approval Actually Decides","article_type":"comparative-study","edition":"research-center","research_question":"部署许可、通道仲裁和动作确认分别在什么对象与时点作决定，哪些权限结论仍不能由它们推出？","summary":"Availability approval, channel arbitration and action confirmation govern different objects. Six internal isolated checks establish local branch behavior, leaving entrance coverage and approval lifecycle unverified.","sources":"https://arxiv.org/html/2611.21259v1; https://docs.ag2.ai/docs/user-guide/network/overview/; https://docs.openhands.dev/sdk/guides/security.md; https://www.servicenow.com/docs/r/intelligent-experiences/ai-control-tower/explore-approvals.html","date":"2026-11-19","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261119-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-19-sig-20261119-001-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-19-sig-20261119-001.md","filePath":"en/engineering/2026-11-19-sig-20261119-001.md","lastUpdated":null}'),d={name:"en/engineering/2026-11-19-sig-20261119-001.md"};function l(h,e,p,u,m,f){const n=t("ArticleCover"),r=t("ArticleTableScroll");return i(),s("div",null,[a(n,{image:"/assets/covers/daily-2026-11-19-sig-20261119-001-cover.png",kicker:"Research",title:"Deployment, Channel, Action: What Each Approval Actually Decides",summary:"Availability approval, channel arbitration and action confirmation govern different objects. Six internal isolated checks establish local branch behavior, leaving entrance coverage and approval lifecycle unverified.",version:"2026-11-19",languageHref:"/zh/engineering/2026-11-19-sig-20261119-001",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=c('<h1 id="deployment-channel-action-what-each-approval-actually-decides" tabindex="-1">Deployment, Channel, Action: What Each Approval Actually Decides <a class="header-anchor" href="#deployment-channel-action-what-each-approval-actually-decides" aria-label="Permalink to &quot;Deployment, Channel, Action: What Each Approval Actually Decides&quot;">​</a></h1><p>A file-reading task has been approved, but its symbolic link points somewhere else by the time it runs. Does the earlier check still authorize this call? Approval to deploy an agent cannot answer that question on its own. Deployment approval, channel arbitration and action confirmation decide different things. An audit becomes more useful when it records who checks what, when they intervene and which paths they exclude.</p><h2 id="the-same-word-conceals-different-decisions" tabindex="-1">The same word conceals different decisions <a class="header-anchor" href="#the-same-word-conceals-different-decisions" aria-label="Permalink to &quot;The same word conceals different decisions&quot;">​</a></h2><p>This is a comparison of documented responsibilities, not a security ranking. ServiceNow&#39;s approvals documentation describes assets or servers requiring approval before becoming available when the relevant feature is activated. That answers whether a capability may be offered. It does not automatically answer whether a particular caller may perform a particular action on a particular target. An available but inactive feature is also not observed enforcement. <a href="https://www.servicenow.com/docs/r/intelligent-experiences/ai-control-tower/explore-approvals.html" target="_blank" rel="noreferrer">Deployment approvals documentation</a></p><p>AG2&#39;s network documentation separates arbitration before a channel decision from listeners that observe afterward. Arbitration can intervene before the transition; a listener can record what happened. The existence of a record does not establish prior authorization. These are documented architectural responsibilities, not a transport-authentication audit performed here. <a href="https://docs.ag2.ai/docs/user-guide/network/overview/" target="_blank" rel="noreferrer">Network overview</a></p><p>OpenHands describes an analyzer assigning action risk and a confirmation policy deciding whether to ask the user. Its security guide explicitly excludes direct tool execution from the analyzer and confirmation policy in the conversation loop. That is a documented coverage boundary; we did not execute a bypass attack. <a href="https://docs.openhands.dev/sdk/guides/security.md" target="_blank" rel="noreferrer">Security guide</a></p><table tabindex="0"><thead><tr><th>Documented check</th><th>Decision object and intervention time</th><th>Question the evidence does not settle</th></tr></thead><tbody><tr><td>Deployment approval</td><td>Before an asset or server becomes available, with the feature activated</td><td>Whether this caller, target and parameter set are authorized</td></tr><tr><td>Channel arbitration</td><td>Before a channel-transition decision</td><td>Whether origin identity is authenticated and every tool entrance is covered</td></tr><tr><td>Listener observation</td><td>After a transition</td><td>Whether that transition was permitted or blocked beforehand</td></tr><tr><td>Action confirmation</td><td>After risk classification and before execution in the covered conversation loop</td><td>What happens on direct calls, recovery entrances and the approval lifecycle</td></tr></tbody></table><p>The product descriptions are source-reported claims from their respective teams. Separately authored descriptions support comparison of objects and timing; they do not constitute mutual replication of one implementation. An unanswered question is not evidence that a product lacks the corresponding control.</p><h2 id="how-far-a-passing-confirmation-function-takes-us" tabindex="-1">How far a passing confirmation function takes us <a class="header-anchor" href="#how-far-a-passing-confirmation-function-takes-us" aria-label="Permalink to &quot;How far a passing confirmation function takes us&quot;">​</a></h2><p>The pinned confirmation predicate has a narrow responsibility. Unknown risk follows a separate confirmation switch. Known risk delegates to the risk comparator with the configured threshold. The threshold itself cannot be unknown. This function decides whether confirmation is needed; it is not a credential system or evidence that all entrances reach it. <a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/141423921fdaeb08cd5f53464a69e860da70b66f/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">Pinned source</a></p><p>Same-day Analysis derived function bodies from this source and ran six isolated checks using an unknown-risk sentinel and a known-risk comparator test double. The following reproduces those existing observations; Production ran no new experiment.</p><table tabindex="0"><thead><tr><th>Input or control</th><th>Internal observation</th></tr></thead><tbody><tr><td>Unknown risk, confirmation enabled</td><td>Confirmation required</td></tr><tr><td>Unknown risk, confirmation disabled</td><td>Confirmation not required</td></tr><tr><td>Known-risk double, comparator returns true</td><td>True returned; threshold passed unchanged</td></tr><tr><td>Known-risk double, comparator returns false</td><td>False returned; threshold passed unchanged</td></tr><tr><td>Unknown value supplied as threshold</td><td>Error rejecting an unknown threshold</td></tr><tr><td>Known object supplied as threshold</td><td>Object returned unchanged</td></tr></tbody></table><p>These are internal experimental observations, not third-party validation. They did not execute the real risk enum&#39;s equality semantics, configuration-model integration or the complete conversation chain. An upstream comment says equality with the threshold requires confirmation; that comment is not a measurement of the real enum in this probe. Current documentation and pinned code are also different revision nodes, so they cannot be combined into one end-to-end pass report.</p><p>The useful result is a responsibility limit. We have internal observations of the switch and comparator delegation. We do not have evidence that every tool call reaches the predicate. Acceptance therefore needs a separate entrance-coverage question rather than a promotion of a function-level pass into a complete authority guarantee.</p><h2 id="inside-the-allowed-directory-can-still-mean-the-wrong-object" tabindex="-1">Inside the allowed directory can still mean the wrong object <a class="header-anchor" href="#inside-the-allowed-directory-can-still-mean-the-wrong-object" aria-label="Permalink to &quot;Inside the allowed directory can still mean the wrong object&quot;">​</a></h2><p>The independently authored four-framework study by Lazer, Aryal, Gupta and Bertino separates changed symbolic links from path containment. The authors report that tested configurations followed a changed link after earlier path validation, while protected configurations could block traversal using canonical checks or a sandbox. Both results can hold: a resource can be inside an allowed directory without remaining the object previously approved. <a href="https://arxiv.org/html/2611.21259v1" target="_blank" rel="noreferrer">Authorization study, section 3.2</a></p><p>The opening file-read is an audit example adapted from that scenario, not a newly observed production incident. Following it produces different questions. Deployment approval establishes availability; arbitration concerns task movement; confirmation identifies risks requiring a decision; current resource resolution determines which file is actually touched. Our interpretation is that earlier permission cannot substitute for evidence about the current target. This does not require four components in every system. It requires an acceptance claim that matches the actual responsibility.</p><p>The study also distinguishes unauthorized tool invocation, host effects and final information disclosure. A request reaching an execution interface and then being stopped is different from a request never reaching that interface. Compressing both into one safe/unsafe label hides the boundary needing repair. <a href="https://arxiv.org/html/2611.21259v1" target="_blank" rel="noreferrer">Study scope and results</a></p><p>Those outcomes remain author-reported; we did not reproduce attack success rates. The study uses a shared model and specified versions and configurations. Enterprise identity and access management, credential authentication and external policy engines were not comprehensively evaluated. Its Microsoft AutoGen sample must not be equated with the current AG2 network documentation.</p><h2 id="audit-one-real-call-instead-of-checking-feature-boxes" tabindex="-1">Audit one real call instead of checking feature boxes <a class="header-anchor" href="#audit-one-real-call-instead-of-checking-feature-boxes" aria-label="Permalink to &quot;Audit one real call instead of checking feature boxes&quot;">​</a></h2><p>The following is a research recommendation, not a unified mechanism established in any sample. Select an actual call, such as reading a reviewed file, and request evidence from the responsible party at each stage.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Input, responsibility and output</th><th>Reason to pause acceptance</th></tr></thead><tbody><tr><td>Offer a capability</td><td>Deployment administrator receives asset configuration and defines availability</td><td>Activation conditions or exclusions are unclear</td></tr><tr><td>Transfer a task</td><td>Application or arbiter receives caller identity and task, then permits a request to proceed</td><td>Only a name or retrospective log exists, without an authority basis</td></tr><tr><td>Obtain confirmation</td><td>Policy and approver receive the concrete action and produce a traceable decision</td><td>Approval is unbound to target, parameters or necessary prior state</td></tr><tr><td>Execute</td><td>Executor receives the request and current resource, producing an effect and record</td><td>The actual entrance skips checks or changed-resource handling is unknown</td></tr><tr><td>Retry or recover</td><td>Recovery receives the prior decision and current state, then continues or requests approval</td><td>Network retry, replay and a newly approvable action cannot be distinguished</td></tr></tbody></table><p>For high-risk operations, separately establish expiry, one-time consumption, invalidation after state changes, and the process or container restrictions backing application checks. Mark missing evidence as unverified. A successful record at another stage cannot fill the gap.</p><p>A counterexample matters: synchronous local confirmation may suffice for a limited single-user threat model. There is no need to add components simply to match the table. Align the threat model, real entrances and acceptance claim. Missing evidence calls for investigation, not an assertion that the product has no control.</p><h2 id="evidence-still-needed" tabindex="-1">Evidence still needed <a class="header-anchor" href="#evidence-still-needed" aria-label="Permalink to &quot;Evidence still needed&quot;">​</a></h2><p>This work did not install the complete SDK or test direct-tool bypass, approval expiry, one-time consumption, replay, recovery revocation or host isolation. The four external teams are independent authors, but they did not cross-replicate one authorization implementation. The six internal checks support only local branch behavior.</p><p>The next verification should pin one real path and version, then compare state changes, retries and renewed approval for the same target. Record separately whether the request entered the tool, whether the host changed and whether information escaped. That is a proposed test, not a completed one. The useful final question is whether the object bound to the decision is still the same object when the effect occurs.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Official documentation supports attributed descriptions; pinned code supports a locally inspectable implementation; internal probes support bounded observations. Comparing decision objects and timing is our interpretation. Publication, citation and the existence of code do not establish general validity.</p><ul><li><a href="https://www.servicenow.com/docs/r/intelligent-experiences/ai-control-tower/explore-approvals.html" target="_blank" rel="noreferrer">ServiceNow deployment and server approvals</a>: official Brazil product documentation, recorded update 2026-09-10; supports activated availability restrictions, without a field deployment test.</li><li><a href="https://docs.ag2.ai/docs/user-guide/network/overview/" target="_blank" rel="noreferrer">AG2 network overview</a>: official architecture documentation, admitted 2026-11-19 snapshot; supports arbiter/listener timing, not an authentication audit.</li><li><a href="https://docs.openhands.dev/sdk/guides/security.md" target="_blank" rel="noreferrer">OpenHands security guide</a>: official documentation captured in the same-day reading; supports confirmation and direct-call boundaries.</li><li><a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/141423921fdaeb08cd5f53464a69e860da70b66f/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">Pinned OpenHands confirmation policy</a>: implementation at the linked commit; tracked separately from current documentation.</li><li><a href="https://arxiv.org/html/2611.21259v1" target="_blank" rel="noreferrer">Four-framework authorization study</a>: first-version paper by the independent author team named above; configuration-specific scenarios and reported results, not independently reproduced here.</li><li>Same-day internal six-case function probe: method, test doubles and actual outputs are retained in this candidate&#39;s evidence package; this is not a complete reproduction of a public system.</li></ul><p>The <a href="/joinwell52/assets/evidence/2026-11-19-sig-20261119-001/authorization-probe.json">six internal case records</a> retain method, test doubles and outputs; they are not an independent reproduction.</p>',31))])}const g=o(d,[["render",l]]);export{v as __pageData,g as default};
